using System.Text.Json;
using System.Text.RegularExpressions;
using System.Security.Cryptography;
using System.Text;
namespace TsRecommend;
internal sealed record CognitionBooking
{
 public string Id{get;init;}="";public string Title{get;init;}="";public string Station{get;init;}="";public string ChannelKey{get;init;}="";public DateTimeOffset Start{get;init;}public DateTimeOffset End{get;init;}public int StartAdjustment{get;init;}public string State{get;init;}="Queued";
 public bool UserSelected{get;init;}public bool UserCancelled{get;init;}public DateTimeOffset? UserActionAt{get;init;}public DateTimeOffset? UserCancelledAt{get;init;}public DateTimeOffset? ObservedAt{get;init;}public string CancellationContext{get;init;}="";
 public string RecommendationKey{get;init;}="";public DateTimeOffset? RecommendationCreatedAt{get;init;}public bool MinimumDurationSuppressed{get;init;}public string RegistrationOrigin{get;init;}="";public string ImportSourceKey{get;init;}="";public string SearchRuleId{get;init;}="";
}
record Recommendation(string ReservationId,string ProgramTitle,string SearchWord,string Reason,DateTimeOffset Start,string Station,string Source="local",DateTimeOffset? CreatedAt=null,DateTimeOffset? End=null,string? Key=null);
record PendingRecommendation(string Key,DateTimeOffset Time);
internal static class CognitionHistory
{
 internal const int Protocol=3;internal const string Algorithm="quantum-cognition-v1";
 internal static readonly JsonSerializerOptions Json=new(){PropertyNamingPolicy=JsonNamingPolicy.CamelCase,PropertyNameCaseInsensitive=true,WriteIndented=true};
 internal static bool Overlap(DateTimeOffset a,DateTimeOffset b,DateTimeOffset c,DateTimeOffset d)=>a<d&&b>c;
 internal static string TimingSeries(string title){int cut=title.IndexOfAny(['【','「','▽','▼','～','〜','—','：']);int space=title.IndexOf(' ');if(space>0&&Regex.IsMatch(title[..space],@"[\u3040-\u30ff\u4e00-\u9fff]")&&(cut<0||space<cut))cut=space;return(cut>0?title[..cut]:title).Trim();}
 static T Locked<T>(string home,Func<T> action){string key=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(Path.GetFullPath(home).ToUpperInvariant())))[..20];using var mutex=new Mutex(false,"Local\\ZooCognition-"+key);bool held=false;try{try{held=mutex.WaitOne(TimeSpan.FromSeconds(5));}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("推薦履歴を更新中です。少し待って再実行してください。");return action();}finally{if(held)mutex.ReleaseMutex();}}
 internal static List<CognitionBooking> Load(string home){string path=Path.Combine(home,"cognition-history.json");return File.Exists(path)?JsonSerializer.Deserialize<List<CognitionBooking>>(ZooStorage.DurableJson.Read(path),Json)??throw new InvalidDataException("推薦履歴が空です。"):[];}
 static void Save(string home,List<CognitionBooking> rows)=>ZooStorage.DurableJson.Write(Path.Combine(home,"cognition-history.json"),JsonSerializer.Serialize(rows,Json));
 internal static bool Matches(Recommendation r,Booking b)=>r.ReservationId==b.Id&&Data.SameStation(r.Station,b.Station)&&Math.Abs((r.Start-b.Start).TotalSeconds)<90;
 internal static List<CognitionBooking> Reconcile(string home,List<Booking> current,List<Recommendation> known,State state,DateTimeOffset now,bool save=true)=>Locked(home,()=>{
  var rows=Load(home);foreach(var b in current){var old=rows.LastOrDefault(x=>x.Id==b.Id&&x.Start==b.Start&&Data.SameStation(x.Station,b.Station));var r=known.LastOrDefault(x=>Matches(x,b));bool cancelled=!b.Enabled;var row=new CognitionBooking{Id=b.Id,Title=b.Title,Station=b.Station,ChannelKey=Data.StationKey(b.Station),Start=b.Start,End=b.End,State=cancelled?"Cancelled":b.End<=now?"Completed":"Queued",UserCancelled=cancelled,UserSelected=old?.UserSelected??(r==null&&b.Manual),UserActionAt=old?.UserActionAt,UserCancelledAt=cancelled?old?.UserCancelledAt:null,ObservedAt=cancelled?(old?.ObservedAt??now):old?.ObservedAt,CancellationContext=cancelled?(old?.CancellationContext??"external-disabled"):"",RecommendationKey=r?.Key??(r!=null?"legacy:"+r.ReservationId:old?.RecommendationKey??""),RecommendationCreatedAt=r?.CreatedAt??old?.RecommendationCreatedAt??(r!=null?(b.Start<now.AddDays(-3)?b.Start:state.CycleStarted??now):null),RegistrationOrigin=r!=null?"自動おすすめ":"手動予約"};if(old!=null)rows.Remove(old);rows.Add(row);}
  // A disappearing future broadcast is a cancellation, not evidence to re-create it.
  foreach(var r in known.Where(r=>!current.Any(b=>Matches(r,b)))){var old=rows.LastOrDefault(x=>x.Id==r.ReservationId&&x.Start==r.Start);bool cancelled=old?.UserCancelled==true||(old?.End??r.End??r.Start)>now;var row=(old??new CognitionBooking{Id=r.ReservationId,Title=r.ProgramTitle,Station=r.Station,ChannelKey=Data.StationKey(r.Station),Start=r.Start,End=r.End??r.Start,RecommendationKey=r.Key??"legacy:"+r.ReservationId,RecommendationCreatedAt=r.CreatedAt??(r.Start<now.AddDays(-3)?r.Start:state.CycleStarted??now)}) with{State=cancelled?"Cancelled":"Completed",UserCancelled=cancelled,ObservedAt=old?.ObservedAt??now};if(old!=null)rows.Remove(old);rows.Add(row);}
  foreach(var old in rows.ToArray())if(!current.Any(b=>b.Id==old.Id&&b.Start==old.Start)&&!known.Any(r=>r.ReservationId==old.Id&&r.Start==old.Start)&&old.End>now){rows.Remove(old);rows.Add(old with{State="Cancelled",UserCancelled=true,ObservedAt=old.ObservedAt??now});}
  if(save)Save(home,rows);return rows;
 });
 internal static void RecordAction(string home,Booking b,bool enabled,DateTimeOffset now){Locked(home,()=>{var rows=Load(home);var old=rows.LastOrDefault(x=>x.Id==b.Id&&x.Start==b.Start);var row=(old??new CognitionBooking{Id=b.Id,Title=b.Title,Station=b.Station,ChannelKey=Data.StationKey(b.Station),Start=b.Start,End=b.End}) with{State=enabled?"Queued":"Cancelled",UserSelected=enabled||old?.UserSelected==true,UserCancelled=!enabled,UserActionAt=enabled?now:old?.UserActionAt,UserCancelledAt=enabled?null:now,ObservedAt=now,CancellationContext=enabled?"":"cancel"};if(old!=null)rows.Remove(old);rows.Add(row);Save(home,rows);return 0;});Schedule(home,now.AddMinutes(2));}
 internal static bool CancelledBroadcast(IEnumerable<CognitionBooking> rows,Show s)=>rows.Any(b=>b.UserCancelled&&Data.SameStation(b.Station,s.Station)&&Math.Abs((b.Start-s.Start).TotalSeconds)<90);
 internal static int Used(List<CognitionBooking> rows,State state,DateTimeOffset now)=>rows.Count(b=>CognitionLearning.CountsAgainstLimit(b,now))+state.Pending.Where(p=>p.Time>now.AddDays(-3)).Select(p=>p.Key).Distinct().Count()+((state.CycleStarted??DateTimeOffset.MinValue)>now.AddDays(-3)?state.LegacyUnconfirmed:0);
 internal static State ReadState(string home){string path=Path.Combine(home,"recommend-state.json");return File.Exists(path)?JsonSerializer.Deserialize<State>(ZooStorage.DurableJson.Read(path),Json)??throw new InvalidDataException("おすすめ実行履歴が空です。"):new();}
 internal static void Schedule(string home,DateTimeOffset due){Locked(home,()=>{var state=ReadState(home);state.PolicyVersion=Protocol;state.InputChangedAt=DateTimeOffset.Now;state.NextDue=due;ZooStorage.DurableJson.Write(Path.Combine(home,"recommend-state.json"),JsonSerializer.Serialize(state,Json));return 0;});}
 internal static void StoreState(string home,State state,DateTimeOffset started){Locked(home,()=>{var current=ReadState(home);if(current.InputChangedAt>started){state.InputChangedAt=current.InputChangedAt;if(current.NextDue!=null&&(state.NextDue==null||current.NextDue<state.NextDue))state.NextDue=current.NextDue;}ZooStorage.DurableJson.Write(Path.Combine(home,"recommend-state.json"),JsonSerializer.Serialize(state,Json));return 0;});}
 internal static void EnsureProtocol(string home){Directory.CreateDirectory(home);if(!File.Exists(Path.Combine(home,"quantum-options.json")))new QuantumCognitionOptions().Save(home);var state=ReadState(home);if(state.PolicyVersion<Protocol)Schedule(home,DateTimeOffset.Now.AddMinutes(2));}
}
